namespace ks{namespace{TimingTablesPartialTest partialTest=nullptr;using T=TimingTablesTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::ReadCounter:return{0x25fe,4};case S::DispatchReciprocal:return{0x2604,2};case S::AwaitReciprocal:return{0x2606,2};case S::DispatchMultiply:return{0x2606,2};case S::AwaitMultiply:return{0x2608,2};case S::SetBase:return{0x260a,6};case S::ReadRate:return{0x2610,6};case S::DivideRate:return{0x2616,2};case S::ClearRateRemainder:return{0x2618,2};case S::SetFactor:return{0x2648,4};case S::ReadMultiplyRate:return{0x264c,6};case S::ScaleRate:return{0x2652,2};case S::DoubleRate:return{0x2654,2};case S::LocateTable:return{t.kind()==K::Reciprocal?0x261au:0x2656u,6};case S::LocateOutput:return{t.kind()==K::Reciprocal?0x2620u:0x265cu,6};case S::SetCount:return{t.kind()==K::Reciprocal?0x2626u:0x2662u,2};case S::ReadTable:return{t.kind()==K::Reciprocal?0x2628u:0x2664u,2};case S::ShiftFirst:return{t.kind()==K::Reciprocal?0x262au:0x2666u,2};case S::ShiftSecond:return{t.kind()==K::Reciprocal?0x262cu:0x2668u,2};case S::ShiftThird:return{0x266a,2};case S::CopySeed:return{0x262e,2};case S::DivideHigh:return{0x2630,2};case S::RetainHigh:return{0x2632,2};case S::ClearLow:return{0x2634,2};case S::DivideLow:return{0x2636,2};case S::CombineHigh:return{0x2638,2};case S::DoubleOutput:return{0x263a,2};case S::MultiplyOutput:return{0x266c,2};case S::WriteOutput:return{t.kind()==K::Reciprocal?0x263cu:0x266eu,4};case S::NextOutput:return{t.kind()==K::Reciprocal?0x2640u:0x2672u,2};case S::NextCount:return{t.kind()==K::Reciprocal?0x2642u:0x2674u,2};case S::Repeat:return{t.kind()==K::Reciprocal?0x2644u:0x2676u,2};case S::Finish:return{t.kind()==K::Counter?0x2602u:t.kind()==K::Initialize?0x2608u:t.kind()==K::Reciprocal?0x2646u:0x2678u,2};default:throw std::runtime_error("Invalid timing tables stage");}}}
bool TimingTablesCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0x25fe||pc==0x2604||pc==0x260a||pc==0x2648){if(selected)throw std::runtime_error("Overlapping timing tables");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Timing tables capacity");selected->emplace(pc==0x25fe?K::Counter:pc==0x2604?K::Initialize:pc==0x260a?K::Reciprocal:K::Multiply,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return uint16_t(h.read16(r==T::Read::Counter?0xffffe6:r==T::Read::Rate?0x1512e:0xf20c+t.index()*2));},[&](unsigned index,uint32_t value){f.store32((t.kind()==K::Reciprocal?0x159f4:0x15a7c)+index*4,int32_t(value));});auto division=[&](uint16_t divisor,auto&out){flag(h,8,divisor&0x8000);flag(h,4,!divisor);out=int32_t(t.divisionPacked());h.clockI(20);};switch(stage){case S::ReadCounter:f.move(v[0].r,t.counter());break;case S::DispatchReciprocal:f.call(0x260a);break;case S::DispatchMultiply:f.call(0x2648);break;case S::SetBase:f.move(v[0].er,0x3e800000);break;case S::ReadRate:case S::ReadMultiplyRate:f.move(v[1].r,t.rate());break;case S::DivideRate:division(t.rate(),v[0].er);break;case S::ClearRateRemainder:v[0].e=h.sub16(v[0].e,v[0].e);break;case S::SetFactor:f.move(v[0].r,0x8312);break;case S::ScaleRate:v[0].er=int32_t(t.scaledRate());h.clockI(20);break;case S::DoubleRate:f.shift(v[0].er,1,true);break;case S::LocateTable:f.move(v[1].er,0xf20c);break;case S::LocateOutput:f.move(v[2].er,t.kind()==K::Reciprocal?0x159f4:0x15a7c);break;case S::SetCount:f.move(v[3].rl,0x22);break;case S::ReadTable:f.move(v[4].r,t.word());v[1].er+=2;h.clockI(2);break;case S::ShiftFirst:case S::ShiftSecond:f.shift(v[4].r,2,true);break;case S::ShiftThird:f.shift(v[4].r,1,true);break;case S::CopySeed:f.move(v[5].er,v[0].er);break;case S::DivideHigh:case S::DivideLow:division(t.word(),v[5].er);break;case S::RetainHigh:f.move(v[4].e,t.high());break;case S::ClearLow:v[5].r=h.sub16(v[5].r,v[5].r);break;case S::CombineHigh:f.move(v[5].e,t.high());break;case S::DoubleOutput:f.shift(v[5].er,1,true);break;case S::MultiplyOutput:v[4].er=int32_t(t.result());h.clockI(20);break;case S::NextOutput:v[2].er=int32_t(uint32_t(v[2].er)+4);break;case S::NextCount:f.inc(v[3].rl,-1);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage==S::DispatchReciprocal||stage==S::DispatchMultiply)h.pc=h.makepc(f.next);else if(stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost){fprintf(stderr,"timing stage %u actual %llu expected %u\n",unsigned(stage),(unsigned long long)(h.cycles-before),cost);throw std::runtime_error("Timing tables clocks differ");}return true;}}

